    exponent = inputs['exponent']
    modulus = inputs['modulus']

    # Convert to list of lists if needed
    if not isinstance(M, list):
        M = M.tolist()

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices modulo mod"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_power(M, exp, mod):
        """Compute M^exp mod using fast exponentiation"""
        if exp == 0:
            return [[1, 0], [0, 1]]  # Identity matrix

        if exp == 1:
            return [[M[i][j] % mod for j in range(2)] for i in range(2)]

        # Initialize result as identity
        result = [[1, 0], [0, 1]]
        base = [[M[i][j] % mod for j in range(2)] for i in range(2)]

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result_matrix = matrix_power(M, exponent, modulus)

    # Sum all entries
    total = sum(sum(row) for row in result_matrix)

    return float(total % modulus)

